import "./styles.css";

import { addProfileBadge, BadgePosition, BadgeUserArgs, ProfileBadge, removeProfileBadge } from "@api/Badges";
import { addMessageDecoration, removeMessageDecoration } from "@api/MessageDecorations";
import definePlugin from "@utils/types";

import { CircleBadge } from "../_shared/CircleBadge";

const BADGE_ID = "eq-arabic-brand";
const NAME = "Dev Esharq";
const RING = "#f59e0b";

// ─── Authorized user list ──────────────────────────────────────────────────────
// Stored as base64(discordSnowflakeId) — light obfuscation only.
// To add a user:  btoa("their-discord-id")  → paste result below.
// To remove:      delete the entry.
const _ENCODED = [
    "NjgxNDY1NzU4MTI3MjI2OTAw",
    "MTA3Mjk2MTQ3NTEyNTE4MjU2NA==",
    "NjgzMDMxNTQ4NjcyNjA2MjY0",
    "MTA0NjU0NTI5MjEwMDY1MzE3Nw==",
    "NTM4Njk5MzE2MjMyMDYwOTM4",
    "MTI5NTQ2NDY3MzI2NDY2NDc0Nw==",
    "MTE2MTM4OTIzOTExMjU2ODkwMg==",
];

const BADGE_USERS: ReadonlySet<string> = new Set(_ENCODED.map(atob));

function hasBadge(userId: string): boolean {
    return BADGE_USERS.has(userId);
}

// ─── Badge visual — circular project icon with gold ring ─────────────────────

const PROJECT_ICON = "data:image/png;base64,";

const EqArabicBadge = ({ size }: { size: number; }) => (
    <CircleBadge size={size} image={PROJECT_ICON} ring={RING} tooltip={NAME} className="eq-arabic-badge" animated />
);

// ─── Profile badge ────────────────────────────────────────────────────────────

const profileBadge: ProfileBadge = {
    id: BADGE_ID,
    key: BADGE_ID,
    description: "Dev Esharq",
    // Discord 1.0.9241 broke the component-badge render patch in the profile popout;
    // iconSrc renders via Discord's native <img>. Only `style` reliably reaches that
    // <img> (Discord overrides className), but inline styles block CSS :hover changes —
    // so spacing stays here and all visual polish (glow/hover/transition) lives in
    // styles.css, targeted via the badge's aria-label. The medallion's gold ring is part
    // of the image. The in-chat MessageDecoration below keeps using the component.
    iconSrc: PROJECT_ICON,
    props: { style: { margin: "0 2px" } },
    position: BadgePosition.START,
    shouldShow: ({ userId }: BadgeUserArgs) => hasBadge(userId),
};

// ─── Core module ──────────────────────────────────────────────────────────────
// required: true → cannot be disabled
// hidden: true   → not listed in plugin settings

export default definePlugin({
    name: "EqArabicBrand",
    description: "Esharq brand badge",
    authors: [],
    required: true,
    hidden: true,
    dependencies: ["BadgeAPI", "MessageDecorationsAPI"],

    start() {
        addProfileBadge(profileBadge);

        addMessageDecoration(BADGE_ID, ({ message }) => {
            if (!hasBadge(message?.author?.id ?? "")) return null;
            return <EqArabicBadge size={18} />;
        });
    },

    stop() {
        removeProfileBadge(profileBadge);
        removeMessageDecoration(BADGE_ID);
    },
});
